H.background();
const v0 = P.v0, a = P.a;
const w = H.W, h = H.H;
const y0 = h * 0.6;
const x0 = w * 0.08, x1 = w * 0.92, span = x1 - x0;
H.line(x0, y0 + 24, x1, y0 + 24, { color: H.colors.axis, width: 2 });
const T = 4;
const tt = t % T;
const vt = v0 + a * tt;
const xt = v0 * tt + 0.5 * a * tt * tt;
const maxX = Math.abs(v0) * T + 0.5 * Math.abs(a) * T * T + 1;
const px = x0 + span * H.clamp(xt / maxX, 0, 1);
const r = 14;
H.circle(px, y0, r, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
const vdir = vt >= 0 ? 1 : -1, adir = a >= 0 ? 1 : -1;
H.arrow(px, y0, px + vdir * (10 + Math.abs(vt) * 8), y0, { color: H.colors.warn, width: 4, head: 11 });
H.arrow(px, y0 + 40, px + adir * (8 + Math.abs(a) * 14), y0 + 40, { color: H.colors.good, width: 3, head: 10 });
H.text("v", px + vdir * (10 + Math.abs(vt) * 8) + vdir * 6, y0 - 8, { color: H.colors.warn, size: 13 });
H.text("a", px + adir * (8 + Math.abs(a) * 14) + adir * 6, y0 + 44, { color: H.colors.good, size: 13 });
H.text("Acceleration:  v = v0 + a t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("v0 = " + v0.toFixed(1) + " m/s   a = " + a.toFixed(1) + " m/s^2   t = " + tt.toFixed(2) + " s   v = " + vt.toFixed(2) + " m/s   x = " + xt.toFixed(2) + " m", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "velocity v", color: H.colors.warn }, { label: "acceleration a", color: H.colors.good }], w - 200, 28);
